import mongoose from 'mongoose';

const MONGODB_URI = 'mongodb+srv://inmocultural_db_user:fIVTKcJ6PLk41elg@mudate.8u0oikg.mongodb.net/mudate?retryWrites=true&w=majority&appName=mudate';

const PropertySchema = new mongoose.Schema({
  slug: { type: String, required: true, unique: true },
  title: String, description: String, price: Number, currency: String,
  operation: String, type: String, ciudad: String, barrio: String,
  provincia: String, ambientes: Number, dormitorios: Number, banos: Number,
  superficie_total: Number, superficie_cubierta: Number,
  images: [String], source: String, source_url: String,
  featured: Boolean, published: Boolean,
}, { timestamps: true });

const Property = mongoose.models?.Property || mongoose.model('Property', PropertySchema);

function slugify(str: string): string {
  return str.toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-').replace(/-+/g, '-')
    .trim().slice(0, 60);
}

function mapProps(raw: any[], ciudad: string, provincia: string) {
  return raw.map(p => ({
    slug: slugify(p.title) + '-mla-' + p.mlaId,
    title: p.title,
    price: p.price,
    currency: p.currency,
    type: p.type,
    ciudad,
    provincia,
    operation: 'venta',
    source: 'mercadolibre',
    source_url: p.source_url,
    superficie_cubierta: p.superficie_cubierta || 0,
    superficie_total: 0,
    dormitorios: p.dormitorios || 0,
    ambientes: p.ambientes || 0,
    banos: 0,
    images: p.img ? [p.img] : [],
    featured: p.currency === 'USD' && p.price > 80000 && !!p.img,
    published: true,
  }));
}

