// ── ASSEMBLE ALL PROPERTIES ───────────────────────────────────────────────────
const properties = [
  ...mapProps(rawJujuy, 'San Salvador de Jujuy', 'Jujuy'),
  ...mapProps(rawLaPampa, 'Santa Rosa', 'La Pampa'),
  ...mapProps(rawSanLuis, 'Merlo', 'San Luis'),
  ...mapProps(rawYerbaBuena, 'Yerba Buena', 'Tucumán'),
];

async function seed() {
  await mongoose.connect(MONGODB_URI);
  let inserted = 0, skipped = 0, errors = 0;
  const byProvincia: Record<string, number> = {};

  for (const p of properties) {
    try {
      await Property.create(p);
      inserted++;
      byProvincia[p.provincia!] = (byProvincia[p.provincia!] || 0) + 1;
    } catch (e: any) {
      if (e.code === 11000) skipped++;
      else { console.error('Error:', e.message); errors++; }
    }
  }

  console.log(`\n✅ Seed completado`);
  console.log(`   Insertadas: ${inserted}`);
  console.log(`   Duplicados ignorados: ${skipped}`);
  console.log(`   Errores: ${errors}`);
  console.log(`\nPor provincia:`);
  for (const [prov, count] of Object.entries(byProvincia)) {
    console.log(`   ${prov}: ${count}`);
  }
  await mongoose.disconnect();
}

seed().catch(console.error);
